def get_auth_context_exa(apiKey, includeUsage=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0378000" if __import__("os").path.isdir("./environment_mix/0378000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # Validate inputs
    if not isinstance(apiKey, str) or not apiKey.strip():
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")
    if includeUsage is None:
        includeUsage = True
    if not isinstance(includeUsage, bool):
        return _err("VALIDATION_ERROR", "includeUsage must be a boolean")

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    usage_ledger = _load("usage_ledger.json")

    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}

    apiKey_clean = apiKey.strip()

    # Authenticate ONLY against client-visible values: api_keys.id (and tolerate workspace_id misuse seen in audits)
    key_row = None
    ws_row = None

    # First: match against api_keys.id
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if apiKey_clean == k.get("id"):
            w = ws_by_id.get(k.get("workspace_id"))
            if isinstance(w, dict) and w.get("status") == "active":
                key_row, ws_row = k, w
                break

    # Tolerate callers accidentally passing a workspace id as apiKey (as shown in audit args):
    # pick any active key in that workspace.
    if key_row is None:
        w = ws_by_id.get(apiKey_clean)
        if isinstance(w, dict) and w.get("status") == "active":
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("status") != "active":
                    continue
                if k.get("workspace_id") == w.get("id"):
                    key_row, ws_row = k, w
                    break

    if not key_row or not ws_row:
        return _err(
            "UNAUTHORIZED",
            "Authentication failed: must provide an active api_keys.id (or a workspace id with at least one active key) and the owning workspace must be active.",
        )

    # Update last_used_at on successful authentication
    updated = False
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            if k.get("last_used_at") != now_iso:
                k["last_used_at"] = now_iso
                k["updated_at"] = now_iso
                updated = True
            break
    if updated:
        _save("api_keys.json", api_keys)

    resp = {
        "api_key": dict(key_row),
        "workspace": dict(ws_row),
        "scopes": ["search", "crawl"],
    }

    if includeUsage:
        # Compute current-month usage from usage_ledger
        start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            next_month = start.replace(year=start.year + 1, month=1)
        else:
            next_month = start.replace(month=start.month + 1)

        def _parse_dt(s):
            if not s or not isinstance(s, str):
                return None
            try:
                return datetime.datetime.fromisoformat(s.replace("Z", "+00:00"))
            except Exception:
                return None

        used_requests = 0
        used_chars = 0
        for e in usage_ledger:
            if not isinstance(e, dict):
                continue
            if e.get("workspace_id") != ws_row.get("id"):
                continue
            billed_at = _parse_dt(e.get("billed_at"))
            if not billed_at:
                continue
            if billed_at.tzinfo is None:
                billed_at = billed_at.replace(tzinfo=datetime.timezone.utc)
            billed_at = billed_at.astimezone(datetime.timezone.utc)
            if not (start <= billed_at < next_month):
                continue
            try:
                used_requests += int(e.get("requests") or 0)
                used_chars += int(e.get("extracted_characters") or 0)
            except Exception:
                # ignore malformed ledger rows
                pass

        req_limit = ws_row.get("monthly_request_limit")
        char_limit = ws_row.get("monthly_char_extract_limit")
        try:
            req_limit_i = int(req_limit)
        except Exception:
            req_limit_i = 0
        try:
            char_limit_i = int(char_limit)
        except Exception:
            char_limit_i = 0

        resp["usage"] = {
            "month_start": start.isoformat(),
            "requests_used": used_requests,
            "requests_limit": req_limit_i,
            "requests_remaining": max(0, req_limit_i - used_requests),
            "extracted_characters_used": used_chars,
            "extracted_characters_limit": char_limit_i,
            "extracted_characters_remaining": max(0, char_limit_i - used_chars),
        }

    resp["meta"] = {"latency_ms": int((time.time() - t0) * 1000)}
    return resp

