    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(x):
        if not x or not isinstance(x, str):
            return None
        try:
            # supports "...Z" and offsets
            if x.endswith("Z"):
                x = x[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(x)
        except Exception:
            return None

    def _month_window(dt):
        start = dt.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        if start.month == 12:
            nxt = start.replace(year=start.year + 1, month=1)
        else:
            nxt = start.replace(month=start.month + 1)
        return start, nxt

    t0 = time.time()
    now_iso = _now_iso()

    # Validation
    if not isinstance(apiKey, str) or not apiKey.strip():
        return _err("VALIDATION_ERROR", "apiKey must be a non-empty string")
