            continue
        if k.get("id") != apiKey_clean:
            continue
        w = ws_by_id.get(k.get("workspace_id"))
        if isinstance(w, dict) and w.get("status") == "active":
            key_row, ws_row = k, w
            break

    # Case B: apiKey matches an active workspace id; pick an active key in that workspace
    if key_row is None:
        w = ws_by_id.get(apiKey_clean)
        if isinstance(w, dict) and w.get("status") == "active":
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("status") != "active":
                    continue
                if k.get("workspace_id") == w.get("id"):
                    key_row, ws_row = k, w
                    break

    if not key_row or not ws_row:
        # Log call (best effort) even on auth failure
        latency_ms = int((time.time() - t0) * 1000)
        # No request log collection exists; usage_ledger is for billing only, so do not write there.
        return _err("UNAUTHORIZED", "API key is missing/invalid/revoked, or workspace is not active")

    # Update last_used_at for observable dynamics
    changed_key = False
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
