        w = ws_by_id.get(k.get("workspace_id"))
        if isinstance(w, dict) and w.get("status") == "active":
            key_row, ws_row = k, w
            break

    if key_row is None:
        w = ws_by_id.get(apiKey_clean)
        if isinstance(w, dict) and w.get("status") == "active":
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("status") != "active":
                    continue
                if k.get("workspace_id") == w.get("id"):
                    key_row, ws_row = k, w
                    break

    if not key_row or not ws_row:
        return _err("UNAUTHORIZED", "API key is missing/invalid/revoked, or workspace is not active")

    # Update last_used_at for observable dynamics
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            k["last_used_at"] = now_iso
            k["updated_at"] = now_iso
            _save("api_keys.json", api_keys)
            break

    # Cancel request with lifecycle enforcement
    if requestType == "search":
        coll = search_requests
        fname = "search_requests.json"
        lifecycle = {"queued": ["running", "cancelled"], "running": ["succeeded", "failed", "cancelled"], "succeeded": [], "failed": [], "cancelled": []}
        id_field = "id"
        ws_field = "workspace_id"
    else:
        coll = crawl_requests
        fname = "crawl_requests.json"
        lifecycle = {"queued": ["running", "cancelled"], "running": ["succeeded", "failed", "cancelled"], "succeeded": [], "failed": [], "cancelled": []}
        id_field = "id"
        ws_field = "workspace_id"

    idx = None
    row = None
    for i, r in enumerate(coll):
        if not isinstance(r, dict):
            continue
        if r.get(id_field) == req_id and r.get(ws_field) == ws_row.get("id"):
            idx = i
            row = r
            break

    if row is None:
        return _err("NOT_FOUND", f"{requestType} request id was not found in the authenticated workspace", id=req_id)

    current = row.get("status")
    if current not in lifecycle:
        return _err("CONFLICT", f"Request has unknown status '{current}' and cannot be cancelled", status=current)

    # Terminal states cannot transition
    if "cancelled" not in lifecycle.get(current, []):
        return _err("INVALID_TRANSITION", f"Cannot cancel a request in terminal state '{current}'", from_status=current, to_status="cancelled")

    # Idempotency: if already cancelled, return row (but lifecycle graph forbids transition, so treat as invalid_transition)
    # Real rule: terminal states refused. cancelled is terminal.
    # Thus, if already cancelled, refuse.
    if current == "cancelled":
        return _err("INVALID_TRANSITION", "Request is already cancelled (terminal state); cannot cancel again", from_status="cancelled", to_status="cancelled")

    # Apply transition
    row["status"] = "cancelled"
    row["updated_at"] = now_iso
    # If running/queued and no finished_at, set finished_at
    if not row.get("finished_at"):
        row["finished_at"] = now_iso
    # Keep started_at as-is; do not invent if missing.
    coll[idx] = row
    _save(fname, coll)

    latency_ms = int((time.time() - t0) * 1000)
    return {
        "data": row,
        "meta": {
            "workspace_id": ws_row.get("id"),
            "api_key_id": key_row.get("id"),
            "request_type": requestType,
            "latency_ms": latency_ms,
            "timestamp": now_iso,
        },
    }
